-- Data demo TernakKu (sintetis): kawanan ±40 ekor, 3 generasi. DIHASILKAN oleh ml/make_demo_seed.mjs.
-- Dipasang ke akun pertama di auth.users. Aman dijalankan ulang (menghapus tag SPI-001 sampai SPI-040 milik akun itu lebih dulu).
do $$
declare v_owner uuid;
begin
  select id into v_owner from auth.users order by created_at limit 1;
  if v_owner is null then raise exception 'Belum ada akun. Daftar dulu lewat aplikasi.'; end if;
  delete from public.livestock where owner_id = v_owner and id in ('SPI-001','SPI-002','SPI-003','SPI-004','SPI-005','SPI-006','SPI-007','SPI-008','SPI-009','SPI-010','SPI-011','SPI-012','SPI-013','SPI-014','SPI-015','SPI-016','SPI-017','SPI-018','SPI-019','SPI-020','SPI-021','SPI-022','SPI-023','SPI-024','SPI-025','SPI-026','SPI-027','SPI-028','SPI-029','SPI-030','SPI-031','SPI-032','SPI-033','SPI-034','SPI-035','SPI-036','SPI-037','SPI-038','SPI-039','SPI-040');
end
$$;
